### sequencia.js rewrite

Need write full file. Let's craft carefully with Angular 1.4 syntax. Use `var` not let/const for legacy browser? Modern browsers support, but keep var to match style.

```
angular.module('deciframeApp').controller('SequenciaController', function($http, $window, ngProgressFactory, $anchorScroll, $location, GENEROS) {
  var CORES = { ... };
  var COR_FALLBACK = '#2E1C74';
  var SUGESTOES = [...];

  var corDoAcorde = function(acorde) {
    var match = /^([A-Ga-g])([#b]?)/.exec(acorde || '');
    if (!match) return COR_FALLBACK;
    var raiz = match[1].toUpperCase() + match[2];
    return CORES[raiz] || COR_FALLBACK;
  };

  var adaptarAcorde = function(acorde) { return {acorde: acorde, cor: corDoAcorde(acorde)}; };
  var adaptarSequencia = function(sequencia) {
    return { id: sequencia.id, origem: sequencia.origem, criado_em: sequencia.criado_em,
             acordes: (sequencia.acordes || []).map(adaptarAcorde) };
  };

  var vm = this;
  vm.sequencias = [];
  vm.sugestoes = SUGESTOES.map(adaptarAcorde);
  vm.novaSequencia = '';
  vm.cadastrando = false;
  vm.carregandoSequencias = false;
  vm.erroCatalogo = '';
  vm.mensagem = '';
  vm.mensagemTipo = '';
  vm.minhaSequencia = {};
  vm.isSearching = false;
  vm.showSearchResultsCount = false;
  vm.esfigeSpeech = "";
  vm.musics = [];
  vm.generos = GENEROS;
  vm.meuGenero = "";
  vm.progressbar = ngProgressFactory.createInstance();

  vm.temAcorde = function(acorde) {
    if (vm.minhaSequencia.acordes) {
      return (vm.minhaSequencia.acordes.indexOf(acorde) > -1);
    }
    return false;
  };

  var limparMensagem = function() { vm.mensagem = ''; vm.mensagemTipo = ''; };
  var mensagem = function(texto, tipo) { vm.mensagem = texto; vm.mensagemTipo = tipo; };

  var carregarSequencias = function(callback) {
    vm.carregandoSequencias = true;
    vm.erroCatalogo = '';
    $http.get('/sequencias')
      .success(function(data) {
        vm.sequencias = (data || []).map(adaptarSequencia);
        vm.carregandoSequencias = false;
        if (callback) callback();
      })
      .error(function() {
        vm.sequencias = [];
        vm.carregandoSequencias = false;
        vm.erroCatalogo = 'Não foi possível carregar o catálogo de sequências.';
        if (callback) callback();
      });
  };
  vm.carregarSequencias = carregarSequencias;

  var parseAcordes = function(texto) {
    var tokens = (texto || '').split(/[\s,]+/);
    var acordes = [];
    for (var i = 0; i < tokens.length; i++) {
      if (tokens[i]) acordes.push(tokens[i]);
    }
    return acordes;
  };
  vm.parseAcordes = parseAcordes; // for tests? not needed but okay.

  vm.adicionarSugestao = function(acorde) {
    var texto = (vm.novaSequencia || '').replace(/\s+$/, '');
    if (texto) {
      vm.novaSequencia = texto + ', ' + acorde;
    } else {
      vm.novaSequencia = acorde;
    }
    limparMensagem();
  };

  var encontrarSequencia = function(id) {
    for (var i=0; i<vm.sequencias.length; i++) {
      if (vm.sequencias[i].id === id) return vm.sequencias[i];
    }
    return null;
  };

  vm.cadastrarSequencia = function() {
    var acordes = parseAcordes(vm.novaSequencia);
    limparMensagem();
    if (!acordes.length) {
      mensagem('Digite ao menos um acorde.', 'danger');
      return;
    }
    vm.cadastrando = true;
    $http.post('/sequencias', {acordes: acordes})
      .success(function(data, status) {
        vm.cadastrando = false;
        if (status === 201) {
          mensagem('Sequência cadastrada.', 'success');
        } else {
          mensagem('Essa sequência já existe; selecionando a existente.', 'info');
        }
        vm.novaSequencia = '';
        carregarSequencias(function() {
          var sequencia = encontrarSequencia(data.id) || adaptarSequencia(data);
          vm.pesquisarPorSequencia(sequencia);
        });
      })
      .error(function(data, status) {
        vm.cadastrando = false;
        if (status === 400) {
          mensagem('Sequência inválida. Informe uma lista de acordes.', 'danger');
        } else if (status === 413) {
          mensagem('O conteúdo enviado é grande demais.', 'danger');
        } else if (status === 429) {
          mensagem('Limite de cadastros atingido. Tente novamente mais tarde.', 'warning');
        } else {
          mensagem('Não foi possível cadastrar a sequência.', 'danger');
        }
      });
  };

  var urlBusca = function() {
    if (!vm.minhaSequencia || vm.minhaSequencia.id === undefined) return null;
    var searchString = '/similares?sequencia_id=' + encodeURIComponent(vm.minhaSequencia.id);
    if (vm.meuGenero !== "" && vm.meuGenero !== null) {
      searchString += '&generos=' + encodeURIComponent(vm.meuGenero);
    }
    return searchString;
  };

  vm.pesquisarPorSequencia = function(sequencia) {
    if (sequencia) {
      vm.minhaSequencia = sequencia;
    }
    var url = urlBusca();
    if (!url) {
      vm.musics = [];
      vm.esfigeSpeech = '';
      vm.isSearching = false;
      vm.showSearchResultsCount = false;
      return;
    }
    vm.progressbar.start();
    vm.esfigeSpeech = "Procurando músicas com base na sequência...";
    vm.isSearching = true;
    vm.showSearchResultsCount = false;
    vm.musics = [];

    $http.get(url)
      .success(function(data) {
        vm.progressbar.complete();
        vm.esfigeSpeech = "Encontrei essas músicas";
        vm.isSearching = false;
        vm.showSearchResultsCount = true;
        vm.musics = data || [];
      })
      .error(function() {
        vm.progressbar.complete();
        vm.esfigeSpeech = "Ops! Algo errado.";
        vm.isSearching = false;
        vm.showSearchResultsCount = false;
        vm.musics = [];
      });
  };

  vm.limparPesquisa = function() {
    vm.minhaSequencia = {};
    vm.musics = [];
    vm.esfigeSpeech = '';
    vm.isSearching = false;
    vm.showSearchResultsCount = false;
    limparMensagem();
  };

  vm.goToLirics = function(music) {
    $window.open(music.url);
  };

  vm.goToResults = function() {
    vm.showSearchResultsCount = false;
    $("body").animate({scrollTop: $("#results").offset().top}, "slow");
  };

  carregarSequencias();
});
