# coding: utf-8
"""Smoke test do servidor real (sem Docker): sobe, cadastra, reinicia, busca."""
import json
import os
import shutil
import subprocess
import sys
import tempfile
import time
import urllib.error
import urllib.request

RAIZ = '/home/Adiel/Documentos/homeworks/ciframe'
PORTA = 5057
BASE = 'http://127.0.0.1:%d' % PORTA


def esperar_servidor():
    limite = time.time() + 180
    while time.time() < limite:
        try:
            with urllib.request.urlopen(BASE + '/generos', timeout=2) as r:
                if r.status == 200:
                    return json.loads(r.read().decode('utf-8'))
        except (urllib.error.URLError, ConnectionError, TimeoutError):
            time.sleep(0.5)
    raise RuntimeError('servidor não respondeu em 180s')


def subir(banco):
    ambiente = dict(os.environ, DECIFRAME_DB=banco)
    return subprocess.Popen(
        [sys.executable, '-c',
         'import main; main.app.run(port=%d, debug=False, use_reloader=False)'
         % PORTA],
        cwd=RAIZ,
        env=ambiente,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )


def get(caminho):
    with urllib.request.urlopen(BASE + caminho, timeout=30) as r:
        return r.status, r.headers.get('Content-Type'), json.loads(
            r.read().decode('utf-8')
        )


def post(caminho, payload):
    dados = json.dumps(payload).encode('utf-8')
    requisicao = urllib.request.Request(
        BASE + caminho,
        data=dados,
        headers={'Content-Type': 'application/json'},
        method='POST',
    )
    try:
        with urllib.request.urlopen(requisicao, timeout=30) as r:
            return r.status, r.headers.get('Content-Type'), json.loads(
                r.read().decode('utf-8')
            )
    except urllib.error.HTTPError as erro:
        return erro.code, erro.headers.get('Content-Type'), json.loads(
            erro.read().decode('utf-8')
        )


def main():
    diretorio = tempfile.mkdtemp(prefix='deciframe-smoke-')
    banco = os.path.join(diretorio, 'deciframe.db')
    processo = None
    try:
        processo = subir(banco)
        generos = esperar_servidor()
        print('generos:', len(generos))

        status, tipo, sequencias = get('/sequencias')
        print('GET /sequencias:', status, tipo, len(sequencias))
        assert [s['id'] for s in sequencias] == list(range(6)), sequencias

        status, tipo, criada = post(
            '/sequencias', {'acordes': ['E', 'B', 'C#m', 'A']}
        )
        print('POST /sequencias:', status, tipo, criada)
        assert status == 201 and criada['id'] == 6, criada

        status, tipo, dados = get(
            '/similares?sequencia_id=6&pagina=1'
        )
        print('GET /similares?sequencia_id=6:', status, tipo, len(dados))
        ids_antes = {m['id_unico_musica'] for m in dados}
        assert status == 200 and dados, dados

        status, tipo, duplicada = post(
            '/sequencias', {'acordes': [' e ', 'b', 'C#M', 'a']}
        )
        print('POST duplicata:', status, duplicada['id'])
        assert status == 200 and duplicada['id'] == 6, duplicada

        processo.terminate()
        processo.wait(timeout=30)
        processo = None
        print('servidor parado; reiniciando...')

        processo = subir(banco)
        esperar_servidor()
        status, tipo, sequencias = get('/sequencias')
        ids = [s['id'] for s in sequencias]
        print('após restart, GET /sequencias:', status, ids)
        assert 6 in ids, ids

        status, tipo, dados = get(
            '/similares?sequencia_id=6&pagina=1'
        )
        ids_depois = {m['id_unico_musica'] for m in dados}
        print('após restart, busca id 6:', status, len(dados))
        assert ids_depois == ids_antes, (ids_antes, ids_depois)

        print('SMOKE LOCAL OK')
    finally:
        if processo is not None:
            processo.terminate()
            try:
                processo.wait(timeout=30)
            except subprocess.TimeoutExpired:
                processo.kill()
        shutil.rmtree(diretorio, ignore_errors=True)


if __name__ == '__main__':
