def coletar_todas_as_paginas(id_seq):
    ids = set()
    pagina = 1
    while True:
        status, tipo, dados = get(
            '/similares?sequencia_id=%d&pagina=%d' % (id_seq, pagina)
        )
        assert status == 200
        if not dados:
            break
        ids.update(item['id_unico_musica'] for item in dados)
        if len(dados) < 100:
            break
        pagina += 1
    return ids

